    private void RegistrarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_RegistrarActionPerformed
                                            
    String sql = "INSERT INTO productos (codigo_barras, nombre, marca, sabor, presentacion, costo_compra, precio_venta, stock) VALUES (?, ?, ?, ?, ?, ?, ?, ?)";
    
    try (Connection con = BD.getConexion();
         PreparedStatement ps = con.prepareStatement(sql)) {
        
        if (con == null) {
            javax.swing.JOptionPane.showMessageDialog(this, "Error de conexión con la base de datos.");
            return;
        }
        
        // Extraer y validar campos de texto
        ps.setString(1, hjaj.getText().trim());
        ps.setString(2, kjay.getText().trim());
        ps.setString(3, ipasi.getText().trim());
        ps.setString(4, iww.getText().trim());
        ps.setString(5, aiaa.getText().trim());
        ps.setDouble(6, Double.parseDouble(ioj.getText().trim()));
        ps.setDouble(7, Double.parseDouble(ohu.getText().trim()));
        ps.setInt(8, Integer.parseInt(iohu.getText().trim()));
        
        ps.executeUpdate();
        
        javax.swing.JOptionPane.showMessageDialog(this, "¡Producto registrado con éxito!");
     this.setVisible(false);
        
    } catch (NumberFormatException e) {
        javax.swing.JOptionPane.showMessageDialog(this, "Por favor, ingresa valores numéricos válidos en Costo, Precio y Stock.", "Error de formato", javax.swing.JOptionPane.WARNING_MESSAGE);
    } catch (Exception e) {
        javax.swing.JOptionPane.showMessageDialog(this, "Error al guardar en la base de datos: " + e.getMessage());
    }

    }//GEN-LAST:event_RegistrarActionPerformed

